package com.bananalab.lite;
import java.io.*;import java.util.*;
public class Stage33Check{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  String root=args[0];Semilla m=SemillaCheck.load(root+"/assets/language");CreatorSession c=new CreatorSession();SceneDraft original=c.apply(m,"crea a Tony una banana detective con sobretodo",null).commit;
  String saved=original.json().toString(),look=original.cast.get(0).look;
  String[] variants={"Tony baila mientras entra el pepino y despues el pepino le entrega una caja a Tony y ambos se sorprenden","el pepino entra mientras Tony baila y luego el pepino entrega una caja a Tony y los dos reaccionan","primero Tony baila mientras el pepino llega por la derecha y despues el pepino pasa una caja a Tony y ambos reaccionan"};
  for(String q:variants){CreatorSession.Result r=c.apply(m,q,original);check(r.commit!=null,"plan: "+r.text);SceneDraft d=r.commit;check(d.cast.size()==2&&d.props.size()==1,"participants");check(d.actions.size()==7,"7 actions "+d.actions);int delivery=d.actions.indexOf("entrega"),receiving=d.actions.indexOf("recibe");check(delivery>=0&&receiving>=0&&d.slot(delivery)==d.slot(receiving),"coordinated delivery");check(d.get("banana").label.equals("tony")&&d.get("banana").look.equals(look),"identity");check(d.recipient(delivery).equals("banana"),"recipient");check(d.slot(0)==d.slot(1),"parallel start");check(ObjectTransfer.at(d,"caja",.05f,4).owner().equals("pepino"),"initial owner");check(ObjectTransfer.at(d,"caja",1,4).owner().equals("banana"),"final owner");ObjectTransfer.State middle=ObjectTransfer.at(d,"caja",.625f,4);check(middle.moving&&Math.abs(middle.blend-.5)<.001,"transfer midpoint");Scene scene=new Scene(d);scene.setSequence(false);check(scene.actorX("pepino",.49f)<73,"physical approach");check(scene.viewAt("banana",.7f)==1&&scene.viewAt("pepino",.7f)==2,"mutual gaze");check(SceneDraft.read(d.json().toString()).recipient(delivery).equals("banana"),"JSON recipients");System.out.println("PASS variant "+q);}
  check(original.json().toString().equals(saved),"transaction original");
  CreatorSession.Result bad=c.apply(m,"Tony baila mientras el pepino entra y despues hace algo imposible",original);check(bad.commit==null,"no partial commit");
  CreatorSession.Result clarify=c.apply(m,"hacelo despues",original);check(clarify.commit==null&&clarify.text.contains("acción"),"clarifies order");
  SceneDraft two=c.apply(m,"agrega otra banana llamada Tina con lentes",original).commit;check(c.apply(m,"la banana baila mientras Tina salta",two).commit==null,"ambiguous duplicate type");
  SceneDraft back=c.apply(m,"pone a Tony de espalda",original).commit;check(back!=null&&back.get("banana").view.equals("back"),"back view command");
  SceneDraft legacy=SceneDraft.read(original.json().toString());check(legacy.get("banana").view.equals("front"),"legacy default");
  CreatorPersistenceCheck.Fake fake=new CreatorPersistenceCheck.Fake();CreatorMemory.save(fake,new CreatorSession(),back);check(CharacterArchive.apply(fake,"usa a tony",new SceneDraft()).scene.cast.get(0).view.equals("back"),"profile view");
  SceneDraft duo=c.apply(m,variants[0],original).commit;CreatorSession.Result moved=c.apply(m,"Tony baila despues de que el pepino entra",duo);check(moved.commit!=null&&moved.commit.slot(0)==1&&moved.commit.slot(1)==0,"relative scheduling "+moved.text);
  CreatorPersistenceCheck.Fake history=new CreatorPersistenceCheck.Fake();CreatorMemory.save(history,new CreatorSession(),duo);SceneDraft changed=duo.copy();changed.get("banana").look="rojo lentes";changed.focused="banana";CreatorMemory.save(history,new CreatorSession(),changed);SceneLibrary.Action restored=CharacterArchive.apply(history,"dejale la ropa de antes",changed);check(restored.scene!=null&&restored.scene.get("banana").look.contains("sobretodo")&&restored.scene.get("banana").look.contains("rojo")&&restored.scene.actions.equals(changed.actions),"clothes without reverting actions");
  SceneDraft mutual=new SceneDraft();mutual.cast.add(new SceneDraft.Actor("banana",20));mutual.cast.add(new SceneDraft.Actor("pepino",80));SceneDirector.step(mutual,mutual.cast.get(0),"acercaactor",0,"","pepino");SceneDirector.step(mutual,mutual.cast.get(1),"acercaactor",0,"","banana");java.util.Map<String,Float> positions=ScenePositions.at(mutual,1);check(Math.abs(positions.get("pepino")-positions.get("banana")-22)<.001,"mutual approach spacing");
  SceneDraft removed=c.apply(m,"quita al pepino",duo).commit;check(removed!=null&&removed.cast.size()==1,"actor removal");SceneDraft.read(removed.json().toString());for(String recipient:removed.recipients)check(!recipient.equals("pepino"),"removed recipient cleanup");
  SceneDraft invalid=duo.copy();invalid.recipients.set(3,"fantasma");boolean rejected=false;try{SceneDraft.read(invalid.json().toString());}catch(Exception expected){rejected=true;}check(rejected,"dangling recipients rejected");
  check(SceneGuide.reply("quien tiene la caja al final",duo).contains("tony"),"grounded ownership query");check(SceneGuide.reply("que significa entregar",duo).contains("sostiene"),"verified explanation");
  CreatorSession.Result namedAction=c.apply(m,"crea a Milo un robot que salta",null);check(namedAction.commit!=null&&namedAction.commit.cast.get(0).label.equals("milo")&&namedAction.commit.actions.contains("salta"),"named design plus action");check(new Scene(duo).viewAt("banana",.9f)==0,"front reaction visibility");
  int[] basePixels=new int[16384],overlayPixels=new int[16384];java.util.Arrays.fill(basePixels,1);java.util.Arrays.fill(overlayPixels,2);int[] glasses=AccessoryMix.apply(basePixels,overlayPixels,0,0,false),hat=AccessoryMix.apply(basePixels,overlayPixels,0,0,true);check(glasses[86*128+70]==2&&glasses[115*128+70]==1,"glasses limited to eye region");check(hat[86*128+70]==1&&hat[4*128+70]==2,"head accessory protects face");check(AccessoryMix.apply(basePixels,overlayPixels,0,3,false)[86*128+70]==1,"no back-facing glasses");
  Scene handoff=new Scene(duo);check(Math.abs(handoff.handX("banana",.7499f)-handoff.handX("banana",.7501f))<.01,"held object stays on same side during front reaction");
  System.out.println("PASS atomic plans, ambiguity, object transfer, gaze, legacy and persistent views");
 }
}
